import{_ as a,c as o,o as i,aj as r}from"./chunks/framework.e3UxQEvm.js";const p=JSON.parse('{"title":"Membership","description":"","frontmatter":{"title":"Membership"},"headers":[],"relativePath":"architecture/membership.md","filePath":"architecture/membership.md"}'),t={name:"architecture/membership.md"};function n(s,e,c,m,d,h){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="membership" tabindex="-1">Membership <a class="header-anchor" href="#membership" aria-label="Permalink to “Membership”">​</a></h1><p>Currently, a person becomes a member of a community when they are added to the community group. This group serves both as a list of members, and a source of truth for data access.</p><h2 id="joining-a-community" tabindex="-1">Joining a Community <a class="header-anchor" href="#joining-a-community" aria-label="Permalink to “Joining a Community”">​</a></h2><p>Person becomes a member when they are added to the community&#39;s group.</p><h3 id="open-groups" tabindex="-1">Open groups <a class="header-anchor" href="#open-groups" aria-label="Permalink to “Open groups”">​</a></h3><p>A person sends a <code>Join</code> activity to community&#39;s inbox, and gets added immediately.</p><h3 id="invitation-only-not-implemented" tabindex="-1">Invitation-only (not implemented) <a class="header-anchor" href="#invitation-only-not-implemented" aria-label="Permalink to “Invitation-only (not implemented)”">​</a></h3><p>Join using an invitation, or get added by other person.</p><h2 id="access-to-resources" tabindex="-1">Access to resources <a class="header-anchor" href="#access-to-resources" aria-label="Permalink to “Access to resources”">​</a></h2><p>Other community members need read access to the hospex profile and accommodations.</p><h3 id="wac" tabindex="-1">WAC <a class="header-anchor" href="#wac" aria-label="Permalink to “WAC”">​</a></h3><p>A resource&#39;s .acl can have <code>acl:agentGroup</code> predicate pointing to a public community&#39;s vcard:Group document with a list of members. This is a primary way of sharing data at the moment. The downside is it&#39;s centralized and community breaks down if the community pod disappears.</p><p>Alternatives:</p><ul><li><code>vcard:Group</code> document can be stored in each member&#39;s pod and updated with a dedicated service or by copying it from contacts.</li><li>each person can be listed via <code>acl:agent</code> in each .acl document.</li></ul><h3 id="acp" tabindex="-1">ACP <a class="header-anchor" href="#acp" aria-label="Permalink to “ACP”">​</a></h3><p>Currently not supported. Would work well if ACP Matchers could be reused. Then we could have a central list of members, or a list for each member, similar to <code>vcard:Group</code> for WAC.</p><h2 id="leaving-a-community" tabindex="-1">Leaving a Community <a class="header-anchor" href="#leaving-a-community" aria-label="Permalink to “Leaving a Community”">​</a></h2><p>TBD</p>',18)])])}const u=a(t,[["render",n]]);export{p as __pageData,u as default};
